const LOGO_BASE64 = "";

const ICON_192_BASE64 = "";

const ICON_512_BASE64 = "";

const LOGO_URL = "https://tiger-ai-team.mohdjarour.workers.dev/assets/logo-signature.png";

const SIGNATURES = {
  "mohamedjarour@tiger-event.com": buildSignatureHtml("Mohamed Jarour", "MANAGER", "+965 6660 2344", "mohamedjarour@tiger-event.com"),
  "tiger@tiger-event.com": buildSignatureHtml("Mohamed Nimer Jarrar", "SALES MANAGER", "99508069", "tiger@tiger-event.com"),
  "mohammed.alshekih@tiger-event.com": buildSignatureHtml("Mohammed Al-Shekih", "SALES REPRESENTATIVE", "9000 7561", "mohammed.alshekih@tiger-event.com"),
  "info.tiger@tiger-event.com": buildSignatureHtml("Tiger Event", "TECHNICAL SUPPORT & INQUIRIES", "66602344", "info.tiger@tiger-event.com"),
};

