export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    const path = url.pathname;

    try {
      // --- الصفحة الرئيسية (اللوحة) ---
      if (path === "/" || path === "") {
        return new Response(DASHBOARD_HTML, {
          headers: { "content-type": "text/html; charset=UTF-8" },
        });
      }

      // --- الشعار المستضاف من نفس المشروع ---
      if (path === "/assets/logo-signature.png") {
        const bytes = base64ToBytes(LOGO_BASE64);
        return new Response(bytes, {
          headers: { "content-type": "image/png", "cache-control": "public, max-age=86400" },
        });
      }
      if (path === "/assets/icon-192.png") {
        const bytes = base64ToBytes(ICON_192_BASE64);
        return new Response(bytes, {
          headers: { "content-type": "image/png", "cache-control": "public, max-age=86400" },
        });
      }
      if (path === "/assets/icon-512.png") {
        const bytes = base64ToBytes(ICON_512_BASE64);
        return new Response(bytes, {
          headers: { "content-type": "image/png", "cache-control": "public, max-age=86400" },
        });
      }
      if (path === "/manifest.json") {
        return json({
          name: "Tiger AI Team",
          short_name: "Tiger AI",
          description: "لوحة قيادة موظفي الذكاء الاصطناعي لشركة Tiger Event",
          start_url: "/",
          scope: "/",
          display: "standalone",
          orientation: "portrait",
          background_color: "#0f1115",
          theme_color: "#1B68AE",
          icons: [
            { src: "/assets/icon-192.png", sizes: "192x192", type: "image/png", purpose: "any maskable" },
            { src: "/assets/icon-512.png", sizes: "512x512", type: "image/png", purpose: "any maskable" },
          ],
        });
      }

      // --- إعداد قاعدة البيانات ---
      if (path === "/setup-db" && request.method === "GET") {
        await setupDatabase(env);
        return json({ ok: true, message: "تم إنشاء الجداول بنجاح" });
      }

      // --- حالة عامة لكل الموظفين ---
      if (path === "/api/status") {
        return json(await getStatus(env));
      }

      // ===================== موظف الموقع =====================
      if (path === "/website/check" && request.method === "POST") {
        return json(await runWebsiteCheck(env));
      }
      if (path === "/website/reports") {
        return json(await getWebsiteReports(env));
      }

      // ===================== موظف بحث الشركات =====================
      if (path === "/leads/generate" && request.method === "POST") {
        const body = await request.json();
        return json(await generateLeads(env, body.sector, body.count || 8));
      }
      if (path === "/leads/list") {
        return json(await getLeads(env));
      }

      // ===================== موظف الإيميلات (Zoho) =====================
      if (path === "/zoho/connect") {
        return Response.redirect(buildZohoAuthUrl(env), 302);
      }
      if (path === "/zoho-callback") {
        return await handleZohoCallback(request, env);
      }
      if (path === "/email/sync" && request.method === "POST") {
        return json(await syncAllZohoInboxes(env));
      }
      if (path === "/email/view") {
        return new Response(await renderEmailViewPage(env), {
          headers: { "content-type": "text/html; charset=UTF-8" },
        });
      }
      if (path === "/email/list") {
        return json(await getEmailInboxSummary(env));
      }
      if (path === "/email/update-draft" && request.method === "POST") {
        const body = await request.json();
        await env.DB.prepare("UPDATE email_log SET draft_reply = ? WHERE id = ?")
          .bind(body.draft, body.id)
          .run();
        return json({ ok: true });
      }
      if (path === "/email/send" && request.method === "POST") {
        const body = await request.json();
        return json(await sendEmailReply(env, body.id));
      }
      if (path === "/zoho/push-signatures" && request.method === "POST") {
        return json(await pushAllSignatures(env));
      }

      return new Response("Not found", { status: 404 });
    } catch (err) {
      return json({ ok: false, error: String(err) }, 500);
    }
  },

  async scheduled(event, env, ctx) {
    ctx.waitUntil(runWebsiteCheck(env));
    ctx.waitUntil(syncAllZohoInboxes(env).catch(() => {}));
  },
};

// ============================================================
// أدوات عامة
// ============================================================
function json(obj, status = 200) {
  return new Response(JSON.stringify(obj, null, 2), {
    status,
    headers: { "content-type": "application/json; charset=UTF-8" },
  });
}

function base64ToBytes(b64) {
  const binStr = atob(b64);
  const bytes = new Uint8Array(binStr.length);
  for (let i = 0; i < binStr.length; i++) bytes[i] = binStr.charCodeAt(i);
  return bytes;
}

async function setupDatabase(env) {
  await env.DB.batch([
    env.DB.prepare(`CREATE TABLE IF NOT EXISTS website_reports (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      created_at TEXT,
      status_code INTEGER,
      response_ms INTEGER,
      notes TEXT
    )`),
    env.DB.prepare(`CREATE TABLE IF NOT EXISTS leads (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      created_at TEXT,
      sector TEXT,
      company_name TEXT,
      sector_type TEXT,
      email TEXT,
      website TEXT,
      draft_email_ar TEXT,
      draft_email_en TEXT
    )`),
    env.DB.prepare(`CREATE TABLE IF NOT EXISTS email_log (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      created_at TEXT,
      zoho_message_id TEXT,
      account_email TEXT,
      account_id TEXT,
      from_addr TEXT,
      subject TEXT,
      summary TEXT,
      draft_reply TEXT,
      status TEXT DEFAULT 'draft'
    )`),
  ]);
}

async function getStatus(env) {
  const website = await env.DB.prepare(
    "SELECT * FROM website_reports ORDER BY id DESC LIMIT 1"
  ).first();
  const leadsCount = await env.DB.prepare(
    "SELECT COUNT(*) as c FROM leads"
  ).first();
  const emailCount = await env.DB.prepare(
    "SELECT COUNT(*) as c FROM email_log"
  ).first();
  const draftCount = await env.DB.prepare(
    "SELECT COUNT(*) as c FROM email_log WHERE status = 'draft'"
  ).first();
  const lastEmail = await env.DB.prepare(
    "SELECT * FROM email_log ORDER BY id DESC LIMIT 1"
  ).first();

  const accounts = getZohoAccounts(env);

  return {
    website: website || null,
    leads_total: leadsCount ? leadsCount.c : 0,
    emails_logged: emailCount ? emailCount.c : 0,
    drafts_pending: draftCount ? draftCount.c : 0,
    last_email: lastEmail || null,
    zoho_connected: accounts.length > 0,
    zoho_accounts_count: accounts.length,
  };
}

// ============================================================
// موظف الموقع
// ============================================================
async function runWebsiteCheck(env) {
  const target = env.WEBSITE_URL || "https://example.com";
  const start = Date.now();
  let statusCode = 0;
  let notes = "";

  try {
    const res = await fetch(target, { redirect: "follow" });
    statusCode = res.status;
    const html = await res.text();
    const checks = [];
    if (!html.includes("<title>")) checks.push("لا يوجد وسم <title>");
    if (!html.match(/<meta[^>]+name=["']description["']/i))
      checks.push("لا يوجد meta description");
    if (!html.match(/<meta[^>]+name=["']viewport["']/i))
      checks.push("لا يوجد meta viewport (مهم للموبايل)");
    notes = checks.length ? checks.join(" | ") : "لا ملاحظات — الموقع سليم";
  } catch (e) {
    notes = "فشل الوصول للموقع: " + String(e);
  }

  const responseMs = Date.now() - start;

  await env.DB.prepare(
    `INSERT INTO website_reports (created_at, status_code, response_ms, notes) VALUES (?, ?, ?, ?)`
  )
    .bind(new Date().toISOString(), statusCode, responseMs, notes)
    .run();

  return { statusCode, responseMs, notes };
}

async function getWebsiteReports(env) {
  const { results } = await env.DB.prepare(
    "SELECT * FROM website_reports ORDER BY id DESC LIMIT 20"
  ).all();
  return results;
}

// ============================================================
// موظف بحث الشركات
// ============================================================
async function generateLeads(env, sector, count) {
  const targetSector = sector && sector.trim()
    ? sector
    : "أقسام التسويق والعلاقات العامة في البنوك، المؤسسات التجارية، المدارس الأجنبية والإنجليزية، والشركات بمختلف أنواعها في الكويت";

  const prompt = `ابحث فعليًا عبر الإنترنت عن ${count} شركات أو مؤسسات حقيقية بالكويت ضمن هذا النطاق: "${targetSector}".
المطلوب تحديدًا: إيميل قسم التسويق (Marketing) أو العلاقات العامة (PR) لكل جهة إن وجد بموقعها الرسمي (وليس إيميل عام أو دعم فني)، ولا تخترع أي إيميل غير موجود فعليًا.
لكل جهة أعطني: الاسم، نوع القطاع (بنك/مدرسة/شركة تجارية/إلخ)، الموقع الإلكتروني، وإيميل قسم التسويق/العلاقات العامة.
ثم اكتب مسودتين لإيميل تعريفي قصير (3-5 أسطر لكل نسخة) تقدّم شركة Tiger Event لتنظيم الفعاليات، وتطلب التسجيل لديهم كمورّد (Vendor) أو منظّم فعاليات (Event Organizer) معتمد:
- نسخة بالعربية الفصحى المهنية
- نسخة بالإنجليزية المهنية (مستقلة، وليست ترجمة حرفية للنسخة العربية)
أعد النتيجة بصيغة JSON فقط بدون أي نص إضافي قبله أو بعده، بالشكل التالي بالضبط:
[{"company_name":"...","sector_type":"...","website":"...","email":"...","draft_email_ar":"...","draft_email_en":"..."}]`;

  let data;
  try {
    const resp = await fetch("https://api.anthropic.com/v1/messages", {
      method: "POST",
      headers: {
        "content-type": "application/json",
        "x-api-key": env.ANTHROPIC_API_KEY,
        "anthropic-version": "2023-06-01",
      },
      body: JSON.stringify({
        model: "claude-sonnet-4-6",
        max_tokens: 4000,
        messages: [{ role: "user", content: prompt }],
        tools: [{ type: "web_search_20250305", name: "web_search" }],
      }),
    });
    data = await resp.json();
  } catch (e) {
    return { ok: false, error: "فشل الاتصال بـ Anthropic API: " + String(e) };
  }

  if (data.error) {
    return { ok: false, error: "خطأ من Anthropic API: " + JSON.stringify(data.error) };
  }
  if (!data.content) {
    return { ok: false, error: "رد غير متوقع من الذكاء الاصطناعي", raw: data };
  }

  const textBlocks = (data.content || [])
    .filter((b) => b.type === "text")
    .map((b) => b.text)
    .join("\n");

  let list = [];
  try {
    const clean = textBlocks.replace(/```json|```/g, "").trim();
    list = JSON.parse(clean);
  } catch (e) {
    return { ok: false, error: "فشل تحليل الرد كـ JSON", raw: textBlocks.slice(0, 1000) };
  }

  for (const item of list) {
    await env.DB.prepare(
      `INSERT INTO leads (created_at, sector, company_name, sector_type, email, website, draft_email_ar, draft_email_en) VALUES (?, ?, ?, ?, ?, ?, ?, ?)`
    )
      .bind(
        new Date().toISOString(),
        targetSector,
        item.company_name || "",
        item.sector_type || "",
        item.email || "",
        item.website || "",
        item.draft_email_ar || "",
        item.draft_email_en || ""
      )
      .run();
  }

  return { ok: true, added: list.length, items: list };
}

async function getLeads(env) {
  const { results } = await env.DB.prepare(
    "SELECT * FROM leads ORDER BY id DESC LIMIT 50"
  ).all();
  return results;
}

// ============================================================
// موظف الإيميلات — دعم عدة حسابات Zoho
// ============================================================
function getZohoAccounts(env) {
  if (env.ZOHO_ACCOUNTS) {
    try {
      return JSON.parse(env.ZOHO_ACCOUNTS);
    } catch (e) {
      return [];
    }
  }
  if (env.ZOHO_REFRESH_TOKEN) {
    return [{ email: "الحساب المتصل", refresh_token: env.ZOHO_REFRESH_TOKEN }];
  }
  return [];
}

function buildZohoAuthUrl(env) {
  const params = new URLSearchParams({
    scope: "ZohoMail.messages.READ,ZohoMail.messages.CREATE,ZohoMail.accounts.READ,ZohoMail.accounts.UPDATE,ZohoMail.accounts.CREATE",
    client_id: env.ZOHO_CLIENT_ID || "",
    response_type: "code",
    redirect_uri: env.ZOHO_REDIRECT_URI || "",
    access_type: "offline",
    prompt: "consent",
  });
  return `https://accounts.zoho.com/oauth/v2/auth?${params.toString()}`;
}

async function handleZohoCallback(request, env) {
  const url = new URL(request.url);
  const code = url.searchParams.get("code");
  if (!code) return json({ ok: false, error: "لا يوجد code بالرابط" }, 400);

  const params = new URLSearchParams({
    grant_type: "authorization_code",
    client_id: env.ZOHO_CLIENT_ID,
    client_secret: env.ZOHO_CLIENT_SECRET,
    redirect_uri: env.ZOHO_REDIRECT_URI,
    code,
  });

  const resp = await fetch(
    `https://accounts.zoho.com/oauth/v2/token?${params.toString()}`,
    { method: "POST" }
  );
  const data = await resp.json();

  // ملاحظة: انسخ refresh_token وأضفه لقائمة ZOHO_ACCOUNTS (Secret) يدويًا
  return json(data);
}

async function getZohoAccessTokenFor(env, refreshToken) {
  const params = new URLSearchParams({
    grant_type: "refresh_token",
    client_id: env.ZOHO_CLIENT_ID,
    client_secret: env.ZOHO_CLIENT_SECRET,
    refresh_token: refreshToken,
  });
  const resp = await fetch(
    `https://accounts.zoho.com/oauth/v2/token?${params.toString()}`,
    { method: "POST" }
  );
  const data = await resp.json();
  if (!data.access_token) {
    throw new Error("فشل تجديد التوكن: " + JSON.stringify(data));
  }
  return data.access_token;
}

async function getZohoAccountInfo(accessToken) {
  const resp = await fetch("https://mail.zoho.com/api/accounts", {
    headers: { Authorization: `Zoho-oauthtoken ${accessToken}` },
  });
  const data = await resp.json();
  const account = data?.data?.[0];
  if (!account) throw new Error("لم يتم العثور على حساب Zoho Mail");
  return account; // { accountId, ... }
}

async function syncAllZohoInboxes(env) {
  const accounts = getZohoAccounts(env);
  if (accounts.length === 0) {
    return { ok: false, error: "لا يوجد أي حساب Zoho مربوط بعد" };
  }

  const results = [];
  for (const acc of accounts) {
    try {
      const r = await syncOneZohoInbox(env, acc);
      results.push({ email: acc.email, ...r });
    } catch (e) {
      results.push({ email: acc.email, ok: false, error: String(e) });
    }
  }
  return { ok: true, accounts: results };
}

async function syncOneZohoInbox(env, account) {
  const accessToken = await getZohoAccessTokenFor(env, account.refresh_token);
  const accInfo = await getZohoAccountInfo(accessToken);
  const accountId = accInfo.accountId;
  const accountEmail = account.email || accInfo.mailboxAddress || accInfo.primaryEmailAddress || "";

  const listResp = await fetch(
    `https://mail.zoho.com/api/accounts/${accountId}/messages/view?limit=10&status=unread`,
    { headers: { Authorization: `Zoho-oauthtoken ${accessToken}` } }
  );
  const listData = await listResp.json();
  const messages = listData?.data || [];

  let processed = 0;
  for (const msg of messages) {
    const existing = await env.DB.prepare(
      "SELECT id FROM email_log WHERE zoho_message_id = ?"
    )
      .bind(msg.messageId)
      .first();
    if (existing) continue;

    const fromAddr = msg.fromAddress || msg.sender || "غير معروف";
    const subject = msg.subject || "(بدون عنوان)";
    const summarySnippet = msg.summary || "";

    const draft = await generateEmailDraftReply(env, fromAddr, subject, summarySnippet);

    await env.DB.prepare(
      `INSERT INTO email_log (created_at, zoho_message_id, account_email, account_id, from_addr, subject, summary, draft_reply, status) VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'draft')`
    )
      .bind(
        new Date().toISOString(),
        msg.messageId || "",
        accountEmail,
        accountId,
        fromAddr,
        subject,
        summarySnippet,
        draft
      )
      .run();
    processed++;
  }

  return { ok: true, checked: messages.length, new_processed: processed };
}

async function generateEmailDraftReply(env, fromAddr, subject, summary) {
  const prompt = `أنت مساعد إيميلات لشركة Tiger Event لتنظيم الفعاليات. وصلت رسالة:
من: ${fromAddr}
الموضوع: ${subject}
مقتطف: ${summary}

اكتشف أولًا لغة الرسالة الأصلية (عربي أو إنجليزي أو أي لغة أخرى)، واكتب مسودة الرد بنفس تلك اللغة بالضبط — لا تترجم ولا تخلط بين اللغتين. اكتب رد قصير ومهني (3-5 أسطر)، مناسب لموضوع الرسالة. إذا كانت الرسالة استفسار عن خدمات، رحّب واطلب تفاصيل أكثر (نوع الفعالية، التاريخ، عدد الحضور). إذا كانت غير واضحة، اكتب ردًا عامًا مهذبًا. أعد فقط نص الرد بدون أي شرح إضافي، وبدون ذكر اللغة المكتشفة.`;

  try {
    const resp = await fetch("https://api.anthropic.com/v1/messages", {
      method: "POST",
      headers: {
        "content-type": "application/json",
        "x-api-key": env.ANTHROPIC_API_KEY,
        "anthropic-version": "2023-06-01",
      },
      body: JSON.stringify({
        model: "claude-sonnet-4-6",
        max_tokens: 500,
        messages: [{ role: "user", content: prompt }],
      }),
    });
    const data = await resp.json();
    const text = (data.content || [])
      .filter((b) => b.type === "text")
      .map((b) => b.text)
      .join("\n");
    return text || "(تعذّر توليد مسودة رد)";
  } catch (e) {
    return "(خطأ أثناء توليد الرد: " + String(e) + ")";
  }
}

async function getEmailInboxSummary(env) {
  const { results } = await env.DB.prepare(
    "SELECT * FROM email_log ORDER BY id DESC LIMIT 50"
  ).all();
  return results;
}

async function sendEmailReply(env, id) {
  const row = await env.DB.prepare("SELECT * FROM email_log WHERE id = ?").bind(id).first();
  if (!row) return { ok: false, error: "الرسالة غير موجودة" };
  if (row.status === "sent") return { ok: false, error: "تم إرسالها مسبقًا" };

  const accounts = getZohoAccounts(env);
  const account = accounts.find((a) => a.email === row.account_email);
  if (!account) return { ok: false, error: "الحساب المرتبط بهذه الرسالة غير موجود ضمن ZOHO_ACCOUNTS" };

  const accessToken = await getZohoAccessTokenFor(env, account.refresh_token);

  const resp = await fetch(`https://mail.zoho.com/api/accounts/${row.account_id}/messages`, {
    method: "POST",
    headers: {
      Authorization: `Zoho-oauthtoken ${accessToken}`,
      "content-type": "application/json",
    },
    body: JSON.stringify({
      fromAddress: row.account_email,
      toAddress: row.from_addr,
      subject: "Re: " + row.subject,
      content: row.draft_reply,
      askReceipt: "no",
    }),
  });
  const data = await resp.json();

  if (resp.ok) {
    await env.DB.prepare("UPDATE email_log SET status = 'sent' WHERE id = ?").bind(id).run();
    return { ok: true, result: data };
  }
  return { ok: false, error: data };
}

// ============================================================
// رفع التوقيعات تلقائيًا لكل حساب متصل
// ============================================================
async function pushAllSignatures(env) {
  const accounts = getZohoAccounts(env);
  const results = [];
  for (const acc of accounts) {
    const html = SIGNATURES[acc.email];
    if (!html) {
      results.push({ email: acc.email, ok: false, error: "لا يوجد توقيع معرّف لهذا الإيميل بالكود" });
      continue;
    }
    try {
      const accessToken = await getZohoAccessTokenFor(env, acc.refresh_token);
      const r = await pushOneSignature(accessToken, html);
      results.push({ email: acc.email, ok: true, result: r });
    } catch (e) {
      results.push({ email: acc.email, ok: false, error: String(e) });
    }
  }
  return { ok: true, results };
}

async function pushOneSignature(accessToken, htmlContent) {
  // المسار الصحيح لتوقيعات Zoho Mail: /api/accounts/signature (بدون accountId)
  const listResp = await fetch(`https://mail.zoho.com/api/accounts/signature`, {
    headers: { Authorization: `Zoho-oauthtoken ${accessToken}` },
  });
  const listData = await listResp.json();
  const list = Array.isArray(listData?.data) ? listData.data : listData?.data ? [listData.data] : [];
  const existing = list[0];
  const existingId = existing?.id || existing?.signatureId;

  if (existingId) {
    const putResp = await fetch(`https://mail.zoho.com/api/accounts/signature`, {
      method: "PUT",
      headers: {
        Authorization: `Zoho-oauthtoken ${accessToken}`,
        "content-type": "application/json",
      },
      body: JSON.stringify({
        id: existingId,
        name: "التوقيع الرسمي",
        content: htmlContent,
        position: 0,
      }),
    });
    return await putResp.json();
  } else {
    const postResp = await fetch(`https://mail.zoho.com/api/accounts/signature`, {
      method: "POST",
      headers: {
        Authorization: `Zoho-oauthtoken ${accessToken}`,
        "content-type": "application/json",
      },
      body: JSON.stringify({
        name: "التوقيع الرسمي",
        content: htmlContent,
        position: 0,
      }),
    });
    return await postResp.json();
  }
}

